(7269249, 1131182, 175946, '<td valign="top">Excellent lighting and background. The water drops and reflector work so well. Good Luck with this one.</td>', 'Excellent lighting and background. The water drops and reflector work so well. Good Luck with this one.', '2014-10-04 11:13:36.000000', NULL, 1),
(7269262, 1130506, 36284, '<td valign="top">to me, image could have been cropped and straightened. I like it.</td>', 'to me, image could have been cropped and straightened. I like it.', '2014-10-04 12:47:15.000000', NULL, 1),
(7269263, 1130742, 36284, '<td valign="top">I dunno. My eyes stray from the skyline to the seagull then to the blue and white thing. Kind of distracting.</td>', 'I dunno. My eyes stray from the skyline to the seagull then to the blue and white thing. Kind of distracting.', '2014-10-04 12:51:25.000000', NULL, 1),
